import $api from "../http";
import { AxiosResponse } from "axios";
import { ICart } from "../intefaces/commonInterfaces";

export default class CartServices {
    static async getCarts(): Promise<AxiosResponse<ICart[]>> {
        try {
            return await $api.get('/cart');
        } catch (error) {
            console.error('Failed to get carts:', error);
            throw error;  // або можна обробити помилку іншим способом
        }
    }

    static async addCart(doctor_id: number, quantity: number, doctor_type: string): Promise<AxiosResponse<any>> {
        try {
            return await $api.post(`/cart`, { doctor_id, quantity, doctor_type });
        } catch (error) {
            console.error('Failed to add to cart:', error);
            throw error; // обробка помилки
        }
    }

    static async deleteCart(item_index: number): Promise<AxiosResponse<any>> {
        try {
            return await $api.delete(`/cart/${item_index}`);
        } catch (error) {
            console.error('Failed to delete from cart:', error);
            throw error; // обробка помилки
        }
    }

    static async clearCart(): Promise<AxiosResponse<void>> {
        try {
            return await $api.delete('/cart');
        } catch (error) {
            console.error('Failed to clear cart:', error);
            throw error; // обробка помилки
        }
    }
}
